import type { ExtensionAPI } from "@mariozechner/pi-coding-agent";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { Type } from "typebox";

export default function (pi: ExtensionAPI) {
  pi.registerTool({
    name: "read",
    label: "read (no truncation)",
    description: "Read file contents. Supports images. No output truncation.",
    parameters: Type.Object({
      path: Type.String({ description: "Path to the file to read (relative or absolute)" }),
      offset: Type.Optional(Type.Number({ description: "Line number to start reading from (1-indexed)" })),
      limit: Type.Optional(Type.Number({ description: "Maximum number of lines to read" })),
    }),
    async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
      const absolutePath = resolve(ctx.cwd, params.path);
      const content = await readFile(absolutePath, "utf-8");
      const lines = content.split("\n");
      const start = params.offset ? Math.max(0, params.offset - 1) : 0;
      const end = params.limit ? start + params.limit : lines.length;
      const text = lines.slice(start, end).join("\n");
      return {
        content: [{ type: "text", text }],
        details: { lines: lines.length },
      };
    },
  });
}

pi.on("tool_result", async (event, ctx) => {
  if (event.toolName !== "read") return;
  const details = event.details as { fullOutputPath?: string } | undefined;
  if (!details?.fullOutputPath) return;
  const fullContent = await readFile(details.fullOutputPath, "utf-8");
  return { content: [{ type: "text", text: fullContent }] };
});

