export function hasListModelsMatch(output: string): boolean {
    const lines = output
        .split("\n")
        .map((line) => line.trim())
        .filter(Boolean);

    return lines.some((line) => {
        if (line.startsWith("provider ") || line.startsWith("No models matching ")) return false;
        return line.split(/\s+/).length >= 2;
    });
}

