const modelThinkingSuffixes = ["off", "minimal", "low", "medium", "high", "xhigh"] as const;

export function modelPatternForListModels(model: string): string {
    const suffixSeparatorIndex = model.lastIndexOf(":");
    if (suffixSeparatorIndex === -1) return model;

    const suffix = model.slice(suffixSeparatorIndex + 1);
    if (!modelThinkingSuffixes.includes(suffix as (typeof modelThinkingSuffixes)[number])) return model;

    return model.slice(0, suffixSeparatorIndex);
}

export function hasListModelsMatch(output: string): boolean {
    const lines = output
        .split("\n")
        .map((line) => line.trim())
        .filter(Boolean);

    return lines.some((line) => !line.startsWith("provider ") && !line.startsWith("No models matching "));
}

return lines.slice(headerIndex + 1).some((line) => {
    if (line.startsWith("No models matching ")) return false;
    const columns = line.split(/\s+/);
    return columns.length >= 2 && columns[0] !== "provider" && columns[1] !== "model";
});

